package com.bank.payrollflatten.service;

import com.bank.payrollflatten.model.Employee;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class PayrollFlattenService {
    private static final Logger log = Logger.getLogger(PayrollFlattenService.class.getName());

    public List<Employee> allEmployees(Map<String, List<Employee>> byDepartment) {
        log.info(() -> "Flattening employees from " + byDepartment.size() + " departments");
        return byDepartment.values().stream()   // Collection<List<Employee>>
                .flatMap(List::stream)           // each inner list → stream, concatenated
                .collect(Collectors.toList());
    }
}
