package com.bank.payrollflatten;

import com.bank.payrollflatten.model.Employee;
import com.bank.payrollflatten.service.PayrollFlattenService;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

public class Main {
    private static final Logger log = Logger.getLogger(Main.class.getName());

    public static void main(String[] args) {
        // LinkedHashMap → predictable insertion-order output.
        Map<String, List<Employee>> byDept = new LinkedHashMap<>();
        byDept.put("IT",    List.of(new Employee("Rajesh"), new Employee("Neha")));
        byDept.put("Sales", List.of(new Employee("Priya")));
        byDept.put("HR",    List.of(new Employee("Amit")));

        List<Employee> all = new PayrollFlattenService().allEmployees(byDept);
        log.info(() -> "All employees for payroll: " + all);
    }
}
